; >S:JIGSAW-CODE; PUT "JIGSAW-CODE";; JIGSAW STUFF;PRPICE;; PRINT THE PIECE OF JIGSAW; IN A BOX IN THE MIDDLE OF; THE SCREEN.;LDX SCREEN   ;* SCREEN NUMBERLDA JIGNUM,X ;* JIG PIECE IN ROOM;ASL AASL AASL A;TAXLDY #0;JIG1;LDA $3EB8,X  ;* CHAR 215-STA JIGBUF,Y;INXINYCPY #8BNE JIG1;; CHAR DATA NOW IN 'JIGBUF';LDA #7STA COUNT;JIG2;LDA COUNTTAYASL ATAX;LDA JIGBUF,Y;PHA;LSR ALSR ALSR ALSR AJSR XPAND;STA $3F80,X  ;* CHAR 240-STA $3F81,X  ;* (DOUBLE HEIGHT);PLA;AND #$FJSR XPAND;STA $3F90,X  ;* CHAR 242-STA $3F91,X  ;* DOUBLE HEIGHT;DEC COUNTBPL JIG2;LDX #15;JIG4;LDY JIGYVL,XLDA JIGCHR,X;STA $DC7-41,Y;LDA JIGCOL,XSTA $DC7-41-$400,Y;DEXBPL JIG4;; NOW IN THE CENTRE OF THE SCREEN;RTS;JIGBUF .BYTE '01234567';JIGYVL;.BYTE $00,$01,$02,$03.BYTE $28,$29,$2A,$2B.BYTE $50,$51,$52,$53.BYTE $78,$79,$7A,$7B;JIGCHR;.BYTE 205,203,203,206.BYTE 204,240,242,204.BYTE 204,241,243,204.BYTE 207,203,203,208;JIGCOL;.BYTE $71,$71,$71,$71.BYTE $71,$42,$42,$71.BYTE $71,$42,$42,$71.BYTE $71,$71,$71,$71;XPAND;STA WORK   ;* SAVE CHAR;LDY #3;JIG3;LSR WORKPHPROR WORK+1PLPROR WORK+1;DEYBPL JIG3;LDA WORK+1;RTS;;;-----------------------------;GOTMES;; PRINT THE MESSAGE IN THE EMPTY; ROOM IF THE PIECE HAS BEEN GOT;LDA #6STA TX;LDA #11STA TY;LDA TEDAND #7ORA #$70STA PRCOL;LDX #0;GORME1;TXAPHA;LDA GOTMS,X;JSR DUBHIT   ;* PRINT DBL;PLATAX;INC TX;INXCPX #19BNE GORME1;; NOW PRINT BOX;; NB X = 19 NOW;GORME2;LDA #203STA $D6E+40,XSTA $D6E+160,X;DEXBPL GORME2;LDX #204STX $D95+40STX $D95+80STX $D95+40+21STX $D95+80+21;; SIDES NOW ON;INX            ;* = 205STX $D6D+40INXSTX $D6D+40+21INXSTX $D6D+160INXSTX $D6D+160+21;; CORNERS ON;LDX #40STX $DA9+40INXSTX $DA9+80;; ! ON;RTS;;GOTMS;;.BYTE 'YOU HAVE THIS PIECE';;;-----------------------------;TRANSF;; TRANSFER THE BIT IN THE MIDDLE; TO THE JIGSAW;LDX SCREENLDA JIGNUM,X;CLCADC #215;STA STOPA;; ACC=JIG CHAR NUM;LDX #0;SHVEIT;; PUT IT IN THE NEXT AVALIABLE; SPACE;LDY RADY,XLDA $E02,Y;CMP #27BNE NKIP;LDA STOPA      ;* GET CHAR;STA $E02,Y     ;* ONTO SCREEN;JMP EATYRE;NKIP;INXCPX #25BNE SHVEIT;EATYRE;LDA #32STA $DC7STA $DC7+40STA $DC8STA $DC8+40;; RUB OUT PIECE ON SCREEN;JSR COLJIG;RTS;;;;.END